// @ts-check
import { ConnectionType } from '../../ConnectionType.js'
import { IConnectionData } from '../../connectionData/IConnectionData.js'
import { getRequire, isNodejsRuntime } from '../../Runtime.js'

const requireDynamic = getRequire(import.meta.url)

/**
 * @typedef {import('../../ConnectionType.js').ConnectionType} ConnectionType
 */

/**
 * Represents TCP connection data.
 * @extends IConnectionData
 */
export class TcpConnectionData extends IConnectionData {
    /** @type {string} */
    ipAddress = ''
    /** @type {number} */
    _port = 0
    /** @type {string} */
    _hostname = ''
    /** @type {ConnectionType} */
    _connectionType = ConnectionType.TCP

    /**
     * @param {string} hostname
     */
    constructor(hostname) {
        super()
        const [hostOnly, port] = TcpConnectionData.#parseHostname(hostname)
        this._port = port
        this._hostname = `${hostOnly}:${port}`
        this._connectionType = ConnectionType.TCP
        if (hostOnly === 'localhost') {
            this.ipAddress = '127.0.0.1'
        } else {
            this.ipAddress = this.resolveIpAddress(hostOnly)
        }
    }

    /**
     * @param {string} hostname
     * @returns {[string, number]}
     */
    static #parseHostname(hostname) {
        let value = String(hostname).trim()
        if (value.toLowerCase().startsWith('tcp://')) {
            value = value.slice(6)
        }
        if (value.includes('/')) {
            throw new Error('TCP addresses do not support route paths.')
        }

        const colon = value.lastIndexOf(':')
        if (colon <= 0 || colon >= value.length - 1) {
            throw new Error('TCP hostname must use host:port format.')
        }

        const hostOnly = value.substring(0, colon).trim()
        const port = Number(value.substring(colon + 1))
        if (!hostOnly || !Number.isInteger(port) || port < 0 || port > 65535) {
            throw new Error('TCP hostname must contain a non-empty host and port between 0 and 65535.')
        }

        return [hostOnly, port]
    }

    /**
     * @returns {ConnectionType}
     */
    get connectionType() {
        return this._connectionType
    }

    get hostname() {
        return this._hostname
    }

    /**
     * @param {string} hostname
     * @returns {string}
     */
    resolveIpAddress(hostname) {
        try {
            if (isNodejsRuntime()) {
                // Check if the input is an IP address
                const ipPattern = /^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/
                if (ipPattern.test(hostname)) {
                    // If it's an IP address, return it directly
                    return hostname
                } else {
                    const dns = requireDynamic('dns')

                    // If it's not an IP address, try to resolve it as a hostname
                    return dns.resolve4(
                        hostname,
                        (/** @type {Error | null} */ err, /** @type {string[]} */ addresses) => {
                            if (err) {
                                console.error(err)
                                return ''
                            }
                            return addresses[0]
                        }
                    )
                }
            }
            return ''
        } catch (error) {
            const err = /** @type {{code?: string}} */ (error)
            if (err.code === 'MODULE_NOT_FOUND') {
                throw new Error('dns module not found. Please install it using npm install dns')
            }
            throw error
        }
    }

    /**
     * Serializes the connection data.
     * @returns {number[]} An array of connection data values.
     */
    serializeConnectionData() {
        let result = [this.connectionType]
        result = result.concat(this._getAddressBytes())
        result = result.concat(this._getPortBytes())
        return result
    }

    /**
     * @returns {number[]} An array of address bytes.
     */
    _getAddressBytes() {
        return this.ipAddress.split('.').map(Number)
    }

    /**
     * @returns {number[]} An array of port bytes.
     */
    _getPortBytes() {
        return [this._port & 0xff, this._port >> 8]
    }

    /**
     * @returns {string}
     */
    toString() {
        return `tcp|${this.hostname}`
    }
}
