// @ts-check
/** @typedef {import('../../InvocationContext.js').InvocationContext} InvocationContext */

import { Command } from '../../../utils/Command.js'
import { CommandType } from '../../../utils/CommandType.js'
import { RuntimeName } from '../../../utils/RuntimeName.js'
import { Duration, Uuid } from '../../../utils/DrawingTypes.js'
import { getCurrentCommandPayload } from './TypeParsingUtils.js'

const PHP_UUID_TYPE = 'HypertubePhpUtils\\Uuid'
const PHP_URI_TYPE = 'HypertubePhpUtils\\Uri'

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseDateTime(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1]).replace(/Z$/, '+00:00')
    return new Date(iso)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {number} total milliseconds
 */
export function parseDateInterval(invocationContext) {
    const arg = getCurrentCommandPayload(invocationContext)[1]
    if (typeof arg === 'number' || /^-?\d+$/.test(String(arg))) {
        return Number(arg) / 10_000
    }
    const match = String(arg).match(/^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)S)?$/)
    if (!match) {
        throw new Error(`Unsupported DateInterval wire value: ${arg}`)
    }
    const hours = Number(match[1] || 0)
    const minutes = Number(match[2] || 0)
    const seconds = Number(match[3] || 0)
    return ((hours * 3600) + (minutes * 60) + seconds) * 1000
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {string}
 */
export function parseUuid(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    const command = invocationContext.getCurrentCommand()
    if (
        command != null &&
        command.commandType === CommandType.InvokeStaticMethod &&
        payload[1] === 'fromString' &&
        payload[2] != null
    ) {
        return String(payload[2])
    }
    return String(payload[1])
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {URL}
 */
export function parseUri(invocationContext) {
    return new URL(String(getCurrentCommandPayload(invocationContext)[1]))
}

/** Inbound: PHP result type string → JavaScript object */
export const PhpTypeParsingFunctions = new Map(
    /** @type {[string, (invocationContext: InvocationContext) => unknown][]} */ ([
        ['DateTime', parseDateTime],
        ['DateTimeImmutable', parseDateTime],
        ['DateInterval', parseDateInterval],
        [PHP_UUID_TYPE, parseUuid],
        [PHP_URI_TYPE, parseUri],
    ])
)

/**
 * @param {Date} value
 * @returns {string}
 */
function phpToIso(value) {
    return value.toISOString().replace(/\.(\d{3})Z$/, (_, millis) => `.${millis.padEnd(6, '0')}Z`)
}

/** Outbound: JavaScript object → Command graph targeting the PHP runtime */
export const PhpParsingArgument = new Map(
    /** @type {[Function, (value: any) => Command][]} */ ([
        [
            Date,
            (/** @type {Date} */ value) =>
                new Command(RuntimeName.Php, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Php, CommandType.GetType, ['DateTimeImmutable']),
                    phpToIso(value),
                ]),
        ],
        [
            URL,
            (/** @type {URL} */ value) =>
                new Command(RuntimeName.Php, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Php, CommandType.GetType, [PHP_URI_TYPE]),
                    value.href,
                ]),
        ],
        [
            Uuid,
            (/** @type {Uuid} */ value) =>
                new Command(RuntimeName.Php, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Php, CommandType.GetType, [PHP_UUID_TYPE]),
                    'fromString',
                    value.value,
                ]),
        ],
        [
            Duration,
            (/** @type {Duration} */ value) =>
                new Command(RuntimeName.Php, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Php, CommandType.GetType, ['DateInterval']),
                    value.milliseconds * 10_000,
                ]),
        ],
    ])
)
