// @ts-check
/** @typedef {import('../../InvocationContext.js').InvocationContext} InvocationContext */

import { Command } from '../../../utils/Command.js'
import { CommandType } from '../../../utils/CommandType.js'
import { RuntimeName } from '../../../utils/RuntimeName.js'
import { getCurrentCommandPayload } from './TypeParsingUtils.js'
import { Color, Duration, Point, Uuid, colorChannel } from '../../../utils/DrawingTypes.js'

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseDateTime(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    // Unspecified-kind DateTime has no offset; treat as UTC
    const hasOffset = iso.endsWith('Z') || /[+-]\d{2}:\d{2}$/.test(iso)
    return new Date(hasOffset ? iso : iso + 'Z')
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseDateTimeOffset(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    return new Date(iso)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {string}
 */
export function parseGuid(invocationContext) {
    return String(getCurrentCommandPayload(invocationContext)[1])
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseTimeOnly(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    // Parse time-only ISO string (e.g. "HH:mm:ss.fffffff") on epoch day
    return new Date(`1970-01-01T${iso}Z`)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {number} total milliseconds
 */
export function parseTimeSpan(invocationContext) {
    const ticks = getCurrentCommandPayload(invocationContext)[1]
    return Number(ticks) / 10_000
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {URL}
 */
export function parseUri(invocationContext) {
    return new URL(String(getCurrentCommandPayload(invocationContext)[1]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Point}
 */
export function parsePoint(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    return new Point(Number(payload[1]), Number(payload[2]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Color}
 */
export function parseColor(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    const a = Number(payload[1]) & 0xff
    const r = Number(payload[2]) & 0xff
    const g = Number(payload[3]) & 0xff
    const b = Number(payload[4]) & 0xff
    return new Color(r, g, b, a)
}

/** Inbound: .NET Core result type string → JavaScript object */
export const NetcoreTypeParsingFunctions = new Map(
    /** @type {[string, (invocationContext: InvocationContext) => unknown][]} */ ([
        ['System.DateTime', parseDateTime],
        ['System.DateTimeOffset', parseDateTimeOffset],
        ['System.Guid', parseGuid],
        ['System.Drawing.Point', parsePoint],
        ['System.Drawing.Color', parseColor],
        ['System.TimeOnly', parseTimeOnly],
        ['System.TimeSpan', parseTimeSpan],
        ['System.Uri', parseUri],
    ])
)

/** Outbound: JavaScript object → Command graph targeting the .NET Core runtime */
export const NetcoreParsingArgument = new Map(
    /** @type {[Function, (value: any) => Command][]} */ ([
        [
            Date,
            (/** @type {Date} */ value) =>
                new Command(RuntimeName.Netcore, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Netcore, CommandType.GetType, ['System.DateTime']),
                    'Parse',
                    value.toISOString(),
                ]),
        ],
        [
            URL,
            (/** @type {URL} */ value) =>
                new Command(RuntimeName.Netcore, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Netcore, CommandType.GetType, ['System.Uri']),
                    value.href,
                ]),
        ],
        [
            Point,
            (/** @type {Point} */ value) =>
                new Command(RuntimeName.Netcore, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Netcore, CommandType.GetType, ['System.Drawing.Point']),
                    value.x,
                    value.y,
                ]),
        ],
        [
            Color,
            (/** @type {Color} */ value) =>
                new Command(RuntimeName.Netcore, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Netcore, CommandType.GetType, ['System.Drawing.Color']),
                    'FromArgb',
                    colorChannel(value.a),
                    colorChannel(value.r),
                    colorChannel(value.g),
                    colorChannel(value.b),
                ]),
        ],
        [
            Duration,
            (/** @type {Duration} */ value) =>
                new Command(RuntimeName.Netcore, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Netcore, CommandType.GetType, ['System.TimeSpan']),
                    value.milliseconds * 10_000,
                ]),
        ],
        [
            Uuid,
            (/** @type {Uuid} */ value) =>
                new Command(RuntimeName.Netcore, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Netcore, CommandType.GetType, ['System.Guid']),
                    value.value,
                ]),
        ],
    ])
)
