// @ts-check
/** @typedef {import('../../InvocationContext.js').InvocationContext} InvocationContext */

import { Command } from '../../../utils/Command.js'
import { CommandType } from '../../../utils/CommandType.js'
import { RuntimeName } from '../../../utils/RuntimeName.js'
import { Color, Duration, Point, TimeOfDay, Uuid, colorChannel } from '../../../utils/DrawingTypes.js'
import { getCurrentCommandPayload } from './TypeParsingUtils.js'

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseTime(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1]).replace(/Z$/, '+00:00')
    return new Date(iso)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {URL}
 */
export function parseUri(invocationContext) {
    return new URL(String(getCurrentCommandPayload(invocationContext)[1]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Uuid}
 */
export function parseUuid(invocationContext) {
    return new Uuid(String(getCurrentCommandPayload(invocationContext)[1]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Duration}
 */
export function parseDuration(invocationContext) {
    const ms = Number(getCurrentCommandPayload(invocationContext)[1])
    return new Duration(ms)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {TimeOfDay}
 */
export function parseTimeOfDay(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    const parsed = new Date(`1970-01-01T${iso}Z`)
    const ms = parsed.getUTCMilliseconds()
    return new TimeOfDay(parsed.getUTCHours(), parsed.getUTCMinutes(), parsed.getUTCSeconds(), ms * 1_000_000)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Point}
 */
export function parsePoint(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    return new Point(Number(payload[1]), Number(payload[2]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Color}
 */
export function parseColor(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    const a = Number(payload[1]) & 0xff
    const r = Number(payload[2]) & 0xff
    const g = Number(payload[3]) & 0xff
    const b = Number(payload[4]) & 0xff
    return new Color(r, g, b, a)
}

/** Inbound: Ruby result type string → JavaScript object */
export const RubyTypeParsingFunctions = new Map(
    /** @type {[string, (invocationContext: InvocationContext) => unknown][]} */ ([
        ['Time', parseTime],
        ['URI', parseUri],
        ['Hypertube::Utils::Uuid', parseUuid],
        ['Uuid', parseUuid],
        ['Hypertube::Utils::Duration', parseDuration],
        ['Duration', parseDuration],
        ['Hypertube::Utils::TimeOfDay', parseTimeOfDay],
        ['TimeOfDay', parseTimeOfDay],
        ['Hypertube::Utils::Point', parsePoint],
        ['Point', parsePoint],
        ['Hypertube::Utils::Color', parseColor],
        ['Color', parseColor],
    ])
)

/**
 * @param {Date} value
 * @returns {string}
 */
function timeToIso(value) {
    return value.toISOString().replace('Z', '+00:00')
}

/** Outbound: JavaScript object → Command graph targeting the Ruby runtime */
export const RubyParsingArgument = new Map(
    /** @type {[Function, (value: any) => Command][]} */ ([
        [
            Date,
            (/** @type {Date} */ value) =>
                new Command(RuntimeName.Ruby, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Ruby, CommandType.GetType, ['Time']),
                    'parse',
                    timeToIso(value),
                ]),
        ],
        [
            URL,
            (/** @type {URL} */ value) =>
                new Command(RuntimeName.Ruby, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Ruby, CommandType.GetType, ['URI']),
                    'parse',
                    value.href,
                ]),
        ],
        [
            Uuid,
            (/** @type {Uuid} */ value) =>
                new Command(RuntimeName.Ruby, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Ruby, CommandType.GetType, ['Hypertube::Utils::Uuid']),
                    value.value,
                ]),
        ],
        [
            Duration,
            (/** @type {Duration} */ value) =>
                new Command(RuntimeName.Ruby, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Ruby, CommandType.GetType, ['Hypertube::Utils::Duration']),
                    value.milliseconds,
                ]),
        ],
        [
            TimeOfDay,
            (/** @type {TimeOfDay} */ value) =>
                new Command(RuntimeName.Ruby, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Ruby, CommandType.GetType, ['Hypertube::Utils::TimeOfDay']),
                    value.hour,
                    value.min,
                    value.sec,
                    value.nsec,
                ]),
        ],
        [
            Point,
            (/** @type {Point} */ value) =>
                new Command(RuntimeName.Ruby, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Ruby, CommandType.GetType, ['Hypertube::Utils::Point']),
                    value.x,
                    value.y,
                ]),
        ],
        [
            Color,
            (/** @type {Color} */ value) =>
                new Command(RuntimeName.Ruby, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Ruby, CommandType.GetType, ['Hypertube::Utils::Color']),
                    colorChannel(value.r),
                    colorChannel(value.g),
                    colorChannel(value.b),
                    colorChannel(value.a),
                ]),
        ],
    ])
)
